files.codeZh:
function saveSettings(s) {
  localStorage.setItem('settings', s.name)
}
function loadSettings() {
  const raw = localStorage.getItem('settings')
  // 保存的是字符串，读取时却当成对象
  return raw.name ? raw : { name: 'Guest' }
}

